import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"2026-10-23 那期\\"科学日报\\"逐条核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/science-news/news-verification-2026-10-23.md","filePath":"topics/science-news/news-verification-2026-10-23.md"}'),e={name:"topics/science-news/news-verification-2026-10-23.md"};function a(i,t,l,g,u,c){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_2026-10-23-那期-科学日报-逐条核实" tabindex="-1">2026-10-23 那期&quot;科学日报&quot;逐条核实 <a class="header-anchor" href="#_2026-10-23-那期-科学日报-逐条核实" aria-label="Permalink to &quot;2026-10-23 那期&quot;科学日报&quot;逐条核实&quot;">​</a></h1><blockquote><p>来源：用户 2026-10-23 18:00 转来的一条<strong>五段式</strong>科学新闻摘要（共 18 条，AI 段标注&quot;36kr&quot;）。 已确认：<strong>这条不是本机 cron 生成的</strong>（本机 cron 输出、知识库、ScienceDaily 仓库里都 grep 不到）。 核实方法：Google News RSS 定位原始报道 → 抓正文 → 与转述逐句比对。</p><p><strong>总判断：18 条都有真实来源，但转述普遍失真，分三类——</strong> ① <strong>时间错位</strong>：6~7 月、2~4 月的旧报道被当成&quot;今日新闻&quot;（如 USC 抗癌细胞、双黑洞、水制氢、超流体量子比特） ② <strong>程度夸大</strong>：benchmark 分数 → &quot;破解/突破&quot;（如 67.25% → &quot;破解黎曼猜想&quot;；49/50 → &quot;98% 世界物理难题&quot;） ③ <strong>主体/口径错位</strong>：个人观点 → &quot;公司宣称&quot;（Jack Clark → &quot;Anthropic 宣称&quot;）；&quot;GDP 总量迈向 44 万亿&quot; → &quot;推高 44 万亿&quot;</p></blockquote><blockquote><p>关键词：科学新闻核实、信源核实、36kr 标题党、AI 标题党、时间错位、程度夸大、主体错位、黎曼猜想 67.25%、TheoPhysEval、GPT-6 Astra、Jack Clark 奇点、ChatGPT Dots、Alexander 病、FOXD1 误写、GFAP、钍-229 核时钟、罗马望远镜、亚马逊地下火、北极南极海冰</p></blockquote><hr><h2 id="🤖-ai-科技-4-条-·-失真最严重" tabindex="-1">🤖 AI 科技（4 条 · 失真最严重） <a class="header-anchor" href="#🤖-ai-科技-4-条-·-失真最严重" aria-label="Permalink to &quot;🤖 AI 科技（4 条 · 失真最严重）&quot;">​</a></h2><h3 id="ai1「openai-之后-ai-再破广义黎曼猜想」" tabindex="-1">AI1「OpenAI 之后，AI 再破广义黎曼猜想」 <a class="header-anchor" href="#ai1「openai-之后-ai-再破广义黎曼猜想」" aria-label="Permalink to &quot;AI1「OpenAI 之后，AI 再破广义黎曼猜想」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 英文站 2026-10-18《Bombshell Breakthrough! After OpenAI, AI Has Once Again Cracked the Generalized Riemann Hypothesis》</li><li><strong>真身</strong>：Anthropic <strong>2026-08-10</strong> 发布的一项研究（比 36Kr 早 <strong>2 个月</strong>）</li><li><strong>真实内容</strong>（依据 Kingy AI 2026-08-10 解读，作者 Curtis Pyke，原文原话）： <ul><li>⚠️ <strong>&quot;Claude did not solve the Riemann hypothesis.&quot;</strong></li><li>Anthropic 称一个<strong>未发布</strong>的 Claude 模型帮助证明了一个<strong>更窄的结果</strong>：<strong>至少 67.25% 的非平凡 ζ 零点在相关渐近意义下是单重的、且位于临界线上</strong></li><li>Anthropic 的公告只描述了<strong>内部验证 + 临时专家评审</strong>，<strong>没有完成常规同行评议的记载</strong></li><li><strong>无法端到端复现</strong>，因为所用研究模型<strong>身份未公开</strong></li></ul></li><li><strong>失真点</strong>：① &quot;破解广义黎曼猜想&quot; ❌（实为&quot;部分零点位于临界线上&quot;的窄结论）② 8 月旧闻当 10 月新闻 ③ 略去&quot;未同行评议 / 不可复现&quot;</li><li><strong>级别</strong>：✅ 已核实（原题 + 日期 + 逐点解读原文）</li></ul><h3 id="ai2「chatgpt-升级-ai-小队-模式-多智能体分工干活-还能查进度」" tabindex="-1">AI2「ChatGPT 升级&quot;AI 小队&quot;模式：多智能体分工干活，还能查进度」 <a class="header-anchor" href="#ai2「chatgpt-升级-ai-小队-模式-多智能体分工干活-还能查进度」" aria-label="Permalink to &quot;AI2「ChatGPT 升级&quot;AI 小队&quot;模式：多智能体分工干活，还能查进度」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 2026-10-19《ChatGPT Gets AI Team Feature &amp; GPT-6 Astra Pro Upgrade: Assign Tasks Separately to Different Members &amp; Track Work》</li><li><strong>真身</strong>：<strong>2026-09-29</strong> OpenAI 发布 <strong>Dots</strong>（always-on AI 智能体&quot;同事&quot;，各自带云电脑）+ <strong>ChatGPT Space</strong>（人机共享工作空间）+ Pages/Slides <ul><li>VentureBeat 2026-09-29《OpenAI launches Dots, always-on AI agent coworkers, and ChatGPT Space where they can collaborate with human teams》</li><li>Engadget 2026-09-29《ChatGPT Space Is A Shared Hub For Work Projects And Personal AI Agents》</li><li>TechCrunch 2026-09-29《OpenAI takes on Microsoft with the launch of what feels a whole lot like ChatGPT&#39;s own office suite》</li><li>ZDNET 2026-09-29《Is ChatGPT your new Google Workspace alternative? Meet Space, Pages, and slides》</li></ul></li><li><strong>失真点</strong>：基本属实；① 时间错位（9-29 发布 → 10-19 才报）② &quot;AI 小队&quot;是中文再包装，官方名 <strong>Dots + ChatGPT Space</strong>；英文媒体普遍读作<strong>对标 Microsoft/Google Workspace 的办公套件</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="ai3「anthropic-宣称-奇点已至-预测-ai-或将美国-gdp-推高-44-万亿美元」" tabindex="-1">AI3「Anthropic 宣称&quot;奇点已至&quot;，预测 AI 或将美国 GDP 推高 44 万亿美元」 <a class="header-anchor" href="#ai3「anthropic-宣称-奇点已至-预测-ai-或将美国-gdp-推高-44-万亿美元」" aria-label="Permalink to &quot;AI3「Anthropic 宣称&quot;奇点已至&quot;，预测 AI 或将美国 GDP 推高 44 万亿美元」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：Yahoo Finance 2026-10-18《Anthropic Co-Founder Jack Clark Sees AI Driving US GDP <strong>Toward $44 Trillion</strong>, Delivering A Nearly <strong>50% Surge By 2030</strong> — &#39;The Singularity Is Here&#39;》；The Rundown AI 2026-10-22《Anthropic&#39;s Jack Clark tells policymakers the singularity has begun》</li><li><strong>真实内容</strong>： <ul><li>说话人是<strong>联合创始人 Jack Clark</strong>（非&quot;Anthropic 公司&quot;），场合是<strong>对政策制定者</strong>讲话</li><li>原话口径：<strong>美国 GDP 到 2030 年迈向 44 万亿美元</strong>，即<strong>增长近 50%</strong></li><li>相关：R&amp;D World 2026-10-23 记其称&quot;<strong>十亿个虚拟科学家即将到来——或者 100 亿</strong>&quot;</li></ul></li><li><strong>失真点</strong>：① &quot;Anthropic 宣称&quot; ❌（个人在政策场合的预测）② &quot;<strong>推高 44 万亿</strong>&quot; ❌（是 GDP <strong>总量</strong>迈向 44 万亿，不是增量 44 万亿）③ 36Kr 另一篇（2026-10-17）竟写成&quot;<strong>Anthropic Valuation Hits $44 Trillion</strong>（Anthropic 估值达 44 万亿）&quot; ❌ <strong>纯属错译</strong></li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="ai4「哈佛×谷歌研究称-gpt-6-astra-已解决-98-世界物理难题-学界争议中」" tabindex="-1">AI4「哈佛×谷歌研究称 GPT-6 Astra 已解决 98% 世界物理难题，学界争议中」 <a class="header-anchor" href="#ai4「哈佛×谷歌研究称-gpt-6-astra-已解决-98-世界物理难题-学界争议中」" aria-label="Permalink to &quot;AI4「哈佛×谷歌研究称 GPT-6 Astra 已解决 98% 世界物理难题，学界争议中」&quot;">​</a></h3><ul><li><strong>原始报道</strong>：36Kr 2026-10-19《Harvard &amp; Google Stunning Research: GPT-6 Astra Solves 98% of the World&#39;s Physics Problems》</li><li><strong>英文一手</strong>：The Decoder 2026-10-15《GPT-6-Astra solves 49 of 50 physics research problems at $2.40 apiece》（作者 Maximilian Schreiner）</li><li><strong>真实内容</strong>： <ul><li>发布的是 <strong>TheoPhysEval</strong> 基准，由 <strong>35 位研究者</strong>发布，机构含 <strong>ICTS（国际理论科学中心）、哈佛大学、KU Leuven、Google DeepMind</strong></li><li>基准含 <strong>50 道未发表的理论物理研究问题</strong>（带可验证答案）</li><li><strong>GPT-6-Astra 解出 49/50</strong>，<strong>每题成本 $2.40</strong>（另有报道表述&quot;低于 3 美元&quot;）</li><li>⚠️ 研究者的<strong>关键限定</strong>：<strong>&quot;缺少 taste（品味）&quot;是突破尚未随之而来的原因之一</strong> —— 即解出计算题 ≠ 做出研究突破</li></ul></li><li><strong>失真点</strong>：① &quot;世界物理难题&quot; ❌（是 50 道<strong>选定的、未发表的</strong>题）② &quot;98%&quot; 数字本身对（49/50）但语境被抽掉 ③ &quot;哈佛×谷歌研究称&quot; ❌（35 人跨国团队发 benchmark，谷歌方为 DeepMind）④ <strong>完全省略&quot;缺少 taste、突破未随之而来&quot;这一限定</strong> —— 而这才是&quot;学界争议&quot;的真实内容</li><li><strong>级别</strong>：✅ 已核实</li><li><strong>备注</strong>：GPT-6 Astra 是 2026-10 真实主力模型 —— The Decoder 另有专题：直接接入机器人清理陌生厨房、<strong>破解 83 年未解的纳粹电文（10 小时）</strong>、UK AISI 测出其<strong>越狱攻击率比前代升高 5 倍</strong></li></ul><hr><h2 id="🧬-生物医学-4-条" tabindex="-1">🧬 生物医学（4 条） <a class="header-anchor" href="#🧬-生物医学-4-条" aria-label="Permalink to &quot;🧬 生物医学（4 条）&quot;">​</a></h2><h3 id="生1「usc-团队找到无限量产抗癌免疫细胞的方法」" tabindex="-1">生1「USC 团队找到无限量产抗癌免疫细胞的方法」 <a class="header-anchor" href="#生1「usc-团队找到无限量产抗癌免疫细胞的方法」" aria-label="Permalink to &quot;生1「USC 团队找到无限量产抗癌免疫细胞的方法」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：Medical Xpress 2026-06-19《A renewable cell source for cancer immunotherapy could make off-the-shelf treatments possible》；ScienceDaily 2026-06-29 与 <strong>2026-10-16</strong>《USC scientists discover how to create a never-ending supply of cancer-fighting cells》；SciTechDaily 2026-07-08</li><li><strong>真实内容</strong>：USC 团队造出<strong>可再生的工程化免疫细胞来源</strong>，使**&quot;货架式（off-the-shelf）&quot;细胞治疗**成为可能；ScienceDaily 原文措辞：&quot;Scientists have created a potentially renewable source of engineered immune cells that fight cancer&quot;</li><li><strong>失真点</strong>：<strong>时间错位</strong> —— 首发在 <strong>6 月</strong>，10-16 那次是 ScienceDaily 重发</li><li><strong>级别</strong>：✅ 已核实（题名 + 日期 + 来源）</li></ul><h3 id="生2「等了-30-年-致命脑病-foxd1-相关神经退行性疾病-终于迎来首个有效药物」" tabindex="-1">生2「等了 30 年，致命脑病（FOXD1 相关神经退行性疾病）终于迎来首个有效药物」 <a class="header-anchor" href="#生2「等了-30-年-致命脑病-foxd1-相关神经退行性疾病-终于迎来首个有效药物」" aria-label="Permalink to &quot;生2「等了 30 年，致命脑病（FOXD1 相关神经退行性疾病）终于迎来首个有效药物」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：STAT 2026-09-03《Ionis wins FDA approval for first drug for Alexander disease, a rare and deadly neurological disorder》；NeurologyLive《FDA Approves <strong>Zilganersen</strong>, First Treatment for Alexander Disease》；<strong>Reuters 2026-09-04《Ionis Pharma prices first FDA-approved treatment for Alexander disease at $285,000 per dose》</strong>；BioSpace（<strong>antisense drug</strong>）；Fierce Pharma；ScienceDaily 2026-10-12《After 30 years, scientists finally have a drug for a deadly brain disease》</li><li><strong>真实内容</strong>：这个&quot;致命脑病&quot;是 <strong>Alexander 病（亚历山大病）</strong>，由 <strong>GFAP 基因</strong>突变引起的罕见致死性神经病。药是 <strong>Ionis 制药的 zilganersen</strong>（反义寡核苷酸 ASO），<strong>2026-09-03 获 FDA 批准</strong>，为<strong>首款</strong> Alexander 病治疗药，定价 <strong>$285,000 / 剂</strong></li><li><strong>失真点</strong>：① <strong>病因基因写错</strong> —— 写成 <strong>FOXD1</strong> ❌（FOXD1 是发育转录因子，与本病无关；实为 <strong>GFAP</strong>）② &quot;等了 30 年&quot; ✔ 与原报道&quot;three decades of research&quot;一致</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="生3「新药通过修复肠道菌群逆转严重脂肪肝」" tabindex="-1">生3「新药通过修复肠道菌群逆转严重脂肪肝」 <a class="header-anchor" href="#生3「新药通过修复肠道菌群逆转严重脂肪肝」" aria-label="Permalink to &quot;生3「新药通过修复肠道菌群逆转严重脂肪肝」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily <strong>2026-10-17</strong>《New drug reverses severe fatty liver disease by repairing the gut》；News-Medical 2026-07-07《New drug candidate treats severe fatty liver disease by improving gut health》；ScienceDaily 2026-07-11</li><li><strong>真实内容</strong>：一款候选药物通过<strong>改善肠道菌群</strong>逆转严重脂肪肝；ScienceDaily 明确标注为<strong>动物研究</strong></li><li><strong>失真点</strong>：① 时间错位（<strong>7 月</strong>已有同类报道）② &quot;动物实验中效果显著&quot; ✔ 与原报道一致（表述准确）</li><li><strong>级别</strong>：✅ 已核实（题名级）</li></ul><h3 id="生4「47-年追踪研究首次锁定-肌肉力量从这一个年龄开始加速流失」" tabindex="-1">生4「47 年追踪研究首次锁定：肌肉力量从这一个年龄开始加速流失」 <a class="header-anchor" href="#生4「47-年追踪研究首次锁定-肌肉力量从这一个年龄开始加速流失」" aria-label="Permalink to &quot;生4「47 年追踪研究首次锁定：肌肉力量从这一个年龄开始加速流失」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-14《A <strong>47-year</strong> study reveals the age when your body starts losing strength》；EMJ 2026-10-19《<strong>Physical Capacity Decline Begins Decades Before Sarcopenia</strong>》；Medical Dialogues 2026-10-20；BGNES 2026-10-20《Human Physical Strength Begins to <strong>Decline After Age 35</strong>》</li><li><strong>关键数字</strong>：<strong>35 岁</strong>起体力/肌力开始下降；衰退<strong>早于&quot;肌少症（sarcopenia）&quot;数十年</strong></li><li><strong>失真点</strong>：表述基本准确；原标题是&quot;开始流失&quot;而非&quot;加速流失&quot;，程度略有加码</li><li><strong>级别</strong>：✅ 已核实</li></ul><h2 id="🚀-太空物理-4-条" tabindex="-1">🚀 太空物理（4 条） <a class="header-anchor" href="#🚀-太空物理-4-条" aria-label="Permalink to &quot;🚀 太空物理（4 条）&quot;">​</a></h2><h3 id="太1「nasa-罗马望远镜日冕仪-开光-成功-性能超出设计预期近-30-」" tabindex="-1">太1「NASA 罗马望远镜日冕仪&quot;开光&quot;成功，性能超出设计预期近 30%」 <a class="header-anchor" href="#太1「nasa-罗马望远镜日冕仪-开光-成功-性能超出设计预期近-30-」" aria-label="Permalink to &quot;太1「NASA 罗马望远镜日冕仪&quot;开光&quot;成功，性能超出设计预期近 30%」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：NASA 官方 Roman blog <strong>2026-10-22《NASA&#39;s Roman Space Telescope Enters Final Commissioning Phase》</strong>、2026-09-30《NASA Checks Roman Guidance System, <strong>Takes First Coronagraph Observation</strong>》；ScienceDaily 2026-10-17《NASA&#39;s Roman Space Telescope exceeds expectations by <strong>nearly 30%</strong>》；NatureWorldNews 2026-10-21《Camera Beats Its <strong>Sharpness</strong> Goal by Nearly 30% After a <strong>Mirror Nudge Smaller Than a Hair</strong>》</li><li><strong>真实内容</strong>：Roman（南希·格雷斯·罗曼太空望远镜）<strong>已在轨</strong>，2026-10-22 进入<strong>科学调试（science commissioning）阶段</strong>；9-30 完成<strong>首次日冕仪观测</strong>；&quot;超预期近 30%&quot;指的是<strong>主相机锐度</strong>（经一次比头发丝还小的镜面微调后）超出指标，<strong>不是日冕仪</strong></li><li><strong>失真点</strong>：① <strong>主体错位</strong> —— 30% 是<strong>主相机锐度</strong>超标，被安到&quot;日冕仪开光&quot;上 ② &quot;开光成功&quot; ✔ 首次日冕仪观测确有其事（9-30）</li><li><strong>级别</strong>：✅ 已核实</li><li>⚠️ <strong>自我更正</strong>：本次核实推翻了我此前&quot;Roman 尚未发射&quot;的印象 —— 它已发射并在轨调试</li></ul><h3 id="太2「天文学家预测-两个巨型黑洞正螺旋接近-最快约-100-年内相撞」" tabindex="-1">太2「天文学家预测：两个巨型黑洞正螺旋接近，最快约 100 年内相撞」 <a class="header-anchor" href="#太2「天文学家预测-两个巨型黑洞正螺旋接近-最快约-100-年内相撞」" aria-label="Permalink to &quot;太2「天文学家预测：两个巨型黑洞正螺旋接近，最快约 100 年内相撞」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-18《Two monster black holes could collide in just 100 years》；<strong>Live Science 2026-04-16《2 supermassive black holes may collide 100 years from now — and Earth would feel it》</strong>；EarthSky 2026-04-10；ScienceAlert 2026-04-09</li><li><strong>真实内容</strong>：一对<strong>超大质量黑洞</strong>正在螺旋接近，可能在<strong>约 100 年内</strong>并合；英文标题明确&quot;<strong>地球会感受到</strong>&quot;（即引力波）</li><li><strong>失真点</strong>：<strong>时间错位</strong> —— <strong>4 月</strong>已首发，10-18 是 ScienceDaily 重发；&quot;100 年&quot;是估算</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="太3「首台核时钟-基于钍-229-问世-精度有望超越现有原子钟」" tabindex="-1">太3「首台核时钟（基于钍-229）问世，精度有望超越现有原子钟」 <a class="header-anchor" href="#太3「首台核时钟-基于钍-229-问世-精度有望超越现有原子钟」" aria-label="Permalink to &quot;太3「首台核时钟（基于钍-229）问世，精度有望超越现有原子钟」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：<strong>Nature 2026-10-07《A thorium-229 optical nuclear clock with feedback loop》</strong>、Nature《A nuclear clock synchronized to ²²⁹Th》；<strong>NYT 2026-10-07《In Vienna and Beijing, the First Nuclear Clocks Begin to Tick》</strong>；APS Physics；<strong>SCMP《China&#39;s thorium-229 nuclear clock beats Vienna&#39;s on stability》</strong></li><li><strong>真实内容</strong>：<strong>两台</strong>核时钟同时亮相 —— <strong>维也纳</strong>一台、<strong>北京</strong>一台；<strong>中国那台在稳定性上胜过维也纳</strong></li><li><strong>失真点</strong>：基本准确；&quot;首台&quot;应为**&quot;首批两台&quot;**（同日发布）</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="太4「nasa-启动月球洞穴勘探-熔岩管或成首个月球基地的天然防辐射掩体」" tabindex="-1">太4「NASA 启动月球洞穴勘探，熔岩管或成首个月球基地的天然防辐射掩体」 <a class="header-anchor" href="#太4「nasa-启动月球洞穴勘探-熔岩管或成首个月球基地的天然防辐射掩体」" aria-label="Permalink to &quot;太4「NASA 启动月球洞穴勘探，熔岩管或成首个月球基地的天然防辐射掩体」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-08《NASA is searching for hidden caves to build its first Moon base》；Space.com 2026-10-08《NASA&#39;s hunting for a secret underground cave on the moon》；Discover 2026-10-07</li><li><strong>真实内容</strong>：NASA 在月球表面寻找<strong>可作基地的天然洞穴/熔岩管</strong>（天然辐射掩体）</li><li><strong>失真点</strong>：基本准确</li><li><strong>级别</strong>：✅ 已核实</li></ul><h2 id="⚡-材料能源-4-条" tabindex="-1">⚡ 材料能源（4 条） <a class="header-anchor" href="#⚡-材料能源-4-条" aria-label="Permalink to &quot;⚡ 材料能源（4 条）&quot;">​</a></h2><h3 id="材1「科学家发现从水制氢的新催化路径-绿氢成本再降一步」" tabindex="-1">材1「科学家发现从水制氢的新催化路径，绿氢成本再降一步」 <a class="header-anchor" href="#材1「科学家发现从水制氢的新催化路径-绿氢成本再降一步」" aria-label="Permalink to &quot;材1「科学家发现从水制氢的新催化路径，绿氢成本再降一步」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-04《Scientists just found a new way to make hydrogen from water》；Phys.org 2026-02-19《Cheaper green hydrogen? New catalyst design cuts energy losses in <strong>AEM electrolyzers</strong>》；Tech Xplore 2026-05-05《Water-splitting catalyst unlocks cheaper hydrogen at <strong>significantly lower temperatures</strong>》</li><li><strong>真实内容</strong>：新型催化剂设计降低电解水（AEM 电解槽）能量损耗，或<strong>在显著更低温度下</strong>制氢</li><li><strong>失真点</strong>：时间错位（<strong>2~5 月</strong>已有报道）；&quot;成本再降一步&quot; ✔ 方向对，但均属实验室阶段</li><li><strong>级别</strong>：✅ 已核实（题名级）</li></ul><h3 id="材2「单原子厚的-量子高速公路-问世-超导电流承载能力突破传统极限」" tabindex="-1">材2「单原子厚的&quot;量子高速公路&quot;问世，超导电流承载能力突破传统极限」 <a class="header-anchor" href="#材2「单原子厚的-量子高速公路-问世-超导电流承载能力突破传统极限」" aria-label="Permalink to &quot;材2「单原子厚的&quot;量子高速公路&quot;问世，超导电流承载能力突破传统极限」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-16《A <strong>quantum highway</strong> just one atom high could transform superconductors》</li><li><strong>真实内容</strong>：一种<strong>仅一个原子高</strong>的结构可显著提升超导体性能</li><li><strong>失真点</strong>：待补细节（机构/期刊）；&quot;突破传统极限&quot;属原标题的&quot;could transform&quot;加码</li><li><strong>级别</strong>：✅ 题名级（待补正文）</li></ul><h3 id="材3「ai-挖掘出-co2→燃料的隐藏化学反应捷径」" tabindex="-1">材3「AI 挖掘出 CO₂→燃料的隐藏化学反应捷径」 <a class="header-anchor" href="#材3「ai-挖掘出-co2→燃料的隐藏化学反应捷径」" aria-label="Permalink to &quot;材3「AI 挖掘出 CO₂→燃料的隐藏化学反应捷径」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-13《AI reveals a hidden chemical shortcut that could turn CO2 into fuel》；SciTechDaily 2026-10-10《Scientists Discover a <strong>Hidden Hydrogen Pathway</strong> That Could Transform CO2 Into Valuable Fuel》；gasworld 2026-10-14《AI method uncovers &#39;hidden&#39; CO2-to-fuel pathways》</li><li><strong>真实内容</strong>：AI 挖出<strong>数千个隐藏化学反应/一条隐藏&quot;氢路径&quot;</strong>，可提升 CO₂ 转化为燃料的效率</li><li><strong>失真点</strong>：基本准确</li><li><strong>级别</strong>：✅ 已核实（题名级）</li></ul><h3 id="材4「新量子比特将错误率降低-100-倍-超流体量子计算迈出关键一步」" tabindex="-1">材4「新量子比特将错误率降低 100 倍，超流体量子计算迈出关键一步」 <a class="header-anchor" href="#材4「新量子比特将错误率降低-100-倍-超流体量子计算迈出关键一步」" aria-label="Permalink to &quot;材4「新量子比特将错误率降低 100 倍，超流体量子计算迈出关键一步」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：ScienceDaily 2026-10-01《This new qubit could be 100 times less error-prone》；Phys.org 2026-09-08《Superfluid qubit could help scale up quantum computers》；QuantumZeitgeist 2026-09-08《<strong>University Of Surrey</strong> Designs <strong>Superfluid Helium</strong> Qubit To Cut Errors By 100x》</li><li><strong>真实内容</strong>：<strong>萨里大学（University of Surrey）<strong>量子科学组提出</strong>基于超流氦</strong>的量子比特设计，论文发在 <strong>npj Quantum Information</strong>；目标是<strong>把错误率降至约 1/100</strong>，用于扩展量子计算机</li><li><strong>失真点</strong>：时间错位（<strong>9 月</strong>发布），10-01 是 ScienceDaily 转载；&quot;降低 100 倍&quot;是<strong>设计目标/预期</strong>，非已实现的器件指标</li><li><strong>级别</strong>：✅ 已核实</li></ul><h2 id="🌍-地球环境-2-条" tabindex="-1">🌍 地球环境（2 条） <a class="header-anchor" href="#🌍-地球环境-2-条" aria-label="Permalink to &quot;🌍 地球环境（2 条）&quot;">​</a></h2><h3 id="地1「北极海冰-2026-年再创新低-南极海冰却意外大幅反弹-两极分化成谜」" tabindex="-1">地1「北极海冰 2026 年再创新低，南极海冰却意外大幅反弹，两极分化成谜」 <a class="header-anchor" href="#地1「北极海冰-2026-年再创新低-南极海冰却意外大幅反弹-两极分化成谜」" aria-label="Permalink to &quot;地1「北极海冰 2026 年再创新低，南极海冰却意外大幅反弹，两极分化成谜」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：NASA 2026-10-13《Antarctic Sea Ice Grows to Its 2026 Maximum》；<strong>PNAS 2026-07-20《Record-low 2025 and 2026 ice extents restore Arctic winter sea-ice decline》</strong>；Phys.org 2026-09-24《Arctic Sea ice reaches 2026 annual minimum extent》；NSIDC《&quot;Stranger Things&quot; in the 2026 Arctic》</li><li><strong>真实内容</strong>：北极海冰 2025/2026 连续创低值，使<strong>此前一度放缓的北极冬季海冰下降趋势&quot;恢复&quot;</strong>；南极海冰则在 2026 年<strong>达到其年度最大值</strong>（即回升）</li><li><strong>失真点</strong>：基本准确；&quot;两极分化成谜&quot;是媒体修辞，PNAS 论文恰恰给出了趋势解释</li><li><strong>级别</strong>：✅ 已核实</li></ul><h3 id="地2「nasa-卫星发现亚马逊雨林地下-隐藏火灾-激增-泥炭地下阴燃难以扑灭」" tabindex="-1">地2「NASA 卫星发现亚马逊雨林地下&quot;隐藏火灾&quot;激增，泥炭地下阴燃难以扑灭」 <a class="header-anchor" href="#地2「nasa-卫星发现亚马逊雨林地下-隐藏火灾-激增-泥炭地下阴燃难以扑灭」" aria-label="Permalink to &quot;地2「NASA 卫星发现亚马逊雨林地下&quot;隐藏火灾&quot;激增，泥炭地下阴燃难以扑灭」&quot;">​</a></h3><ul><li><strong>真实报道</strong>：<strong>NASA Earth Observatory 2026-10-16/17《NASA discovers hidden fires burning beneath the Amazon rainforest》</strong>（ScienceDaily 2026-10-17 转载，署名 NASA Earth Observatory，MODIS 数据）</li><li><strong>真实内容</strong>：原文摘要：&quot;<strong>El Niño is fueling a dangerous cascade of wildfires across the tropics</strong>, with the Amazon rainforest now experiencing widespread burning and scientists warning that the worst may still be ahead. NASA researchers are uncovering <strong>dozens of previously undetected fires</strong>, suggesting the destruction could be <strong>even more extensive than satellite records show</strong>.&quot;</li><li><strong>失真点</strong>：① &quot;<strong>地下</strong>火灾/泥炭阴燃&quot;是外加的 —— NASA 原文核心是&quot;<strong>数十处此前未被探测到的火</strong>&quot;（隐藏在卫星记录之外），&quot;地下阴燃&quot;更像是把印尼泥炭火的特征嫁接过来 ② &quot;两极分化&quot;式修辞</li><li><strong>级别</strong>：✅ 已核实（有原文摘要）</li></ul>',46)])])}const q=o(e,[["render",a]]);export{d as __pageData,q as default};
